import '../models/post.dart';
import '../models/comment.dart';

class PostApi {
  static Future<List<PostItem>> getAllPosts() async {
    await Future.delayed(const Duration(milliseconds: 300));
    return List.from(_mockPosts);
  }

  static Future<PostItem?> getPostById(String id) async {
    await Future.delayed(const Duration(milliseconds: 100));
    try {
      return _mockPosts.firstWhere((p) => p.id == id);
    } catch (_) {
      return null;
    }
  }

  static Future<List<PostComment>> getCommentsForPost(String postId) async {
    await Future.delayed(const Duration(milliseconds: 200));
    return _mockComments.where((c) => c.postId == postId).toList();
  }

  static Future<PostComment> addComment(PostComment comment) async {
    await Future.delayed(const Duration(milliseconds: 200));
    _mockComments.add(comment);
    return comment;
  }

